def renomear_grupos_forward(apps, schema_editor):
    """
    Renomeia grupos para padronização:
    - Superintendentes → Superintendente EBD (singular)
    - Lider Igreja → Pastor Regional (mais específico)
    - Secretario → Secretario Local (evita ambiguidade)
    """
    Group = apps.get_model('auth', 'Group')
    
    # Mapeamento: nome_antigo → nome_novo
    renomeacoes = [
        ('Superintendentes', 'Superintendente EBD'),
        ('Lider Igreja', 'Pastor Regional'),
        ('Secretario', 'Secretario Local'),
    ]
    
